operations.createDemo:
export const createDemo = <ThrowOnError extends boolean = false>(
  options: Options<CreateDemoData, ThrowOnError>,
) =>
  (options.client ?? client).post<
    CreateDemoResponses,
    CreateDemoErrors,
    ThrowOnError
  >({
    url: "/api/demos",
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options.headers,
    },
  });

operations.deleteDemo:
export const deleteDemo = <ThrowOnError extends boolean = false>(
  options: Options<DeleteDemoData, ThrowOnError>,
) =>
  (options.client ?? client).delete<
    DeleteDemoResponses,
    DeleteDemoErrors,
    ThrowOnError
  >({ url: "/api/demos/{id}", ...options });

operations.getDemo:
export const getDemo = <ThrowOnError extends boolean = false>(
  options: Options<GetDemoData, ThrowOnError>,
) =>
